#include "domain/WorkOrderStateMachine.h"
#include <iostream>
#include <set>
#include <stdexcept>
#include <vector>

using namespace campusfix;
int main() {
    try {
        int checks=0;auto check=[&](bool ok){if(!ok) throw std::runtime_error("State machine mismatch");++checks;};
        using A=WorkflowAction;using E=WorkflowEffect;
        // Independent expected matrix transcribed from frozen flows T-01..T-23, not generated by the implementation.
        const std::vector<WorkflowRule> expected={
            {"T-01",A::Create,std::nullopt,"DRAFT",E::Creation},
            {"T-02",A::Submit,"DRAFT","PENDING_REVIEW",E::StateChange},
            {"T-03",A::ApproveReview,"PENDING_REVIEW","PENDING_DISPATCH",E::StateChange},
            {"T-04",A::ReturnForSupplement,"PENDING_REVIEW","PENDING_SUPPLEMENT",E::StateChange},
            {"T-05",A::Submit,"PENDING_SUPPLEMENT","PENDING_REVIEW",E::StateChange},
            {"T-06",A::RejectReview,"PENDING_REVIEW","CANCELLED",E::StateChange},
            {"T-07",A::Cancel,"DRAFT","CANCELLED",E::StateChange},
            {"T-08",A::Cancel,"PENDING_REVIEW","CANCELLED",E::StateChange},
            {"T-09",A::Cancel,"PENDING_SUPPLEMENT","CANCELLED",E::StateChange},
            {"T-10",A::Recommend,"PENDING_DISPATCH","PENDING_DISPATCH",E::ReadOnly},
            {"T-11",A::Assign,"PENDING_DISPATCH","PENDING_ACCEPT",E::StateChange},
            {"T-12",A::Cancel,"PENDING_DISPATCH","CANCELLED",E::StateChange},
            {"T-13",A::Accept,"PENDING_ACCEPT","IN_PROGRESS",E::StateChange},
            {"T-14",A::Refuse,"PENDING_ACCEPT","PENDING_DISPATCH",E::StateChange},
            {"T-15",A::RequestTransfer,"PENDING_ACCEPT","PENDING_ACCEPT",E::SameStateEvent},
            {"T-16",A::RequestTransfer,"IN_PROGRESS","IN_PROGRESS",E::SameStateEvent},
            {"T-17",A::ApproveTransfer,"PENDING_ACCEPT","PENDING_DISPATCH",E::StateChange},
            {"T-18",A::ApproveTransfer,"IN_PROGRESS","PENDING_DISPATCH",E::StateChange},
            {"T-19",A::Complete,"IN_PROGRESS","PENDING_VERIFY",E::StateChange},
            {"T-20",A::VerifyPass,"PENDING_VERIFY","COMPLETED",E::StateChange},
            {"T-21",A::VerifyFail,"PENDING_VERIFY","IN_PROGRESS",E::StateChange},
            {"T-22",A::Evaluate,"COMPLETED","COMPLETED",E::SameStateEvent},
            {"T-23",A::Close,"COMPLETED","CLOSED",E::StateChange}
        };
        const std::set<std::string_view> statuses={"DRAFT","PENDING_REVIEW","PENDING_SUPPLEMENT","PENDING_DISPATCH","PENDING_ACCEPT",
            "IN_PROGRESS","PENDING_VERIFY","COMPLETED","CLOSED","CANCELLED"};
        check(std::set<std::string_view>(WorkOrderStateMachine::states().begin(),WorkOrderStateMachine::states().end())==statuses);
        check(WorkOrderStateMachine::rules().size()==23);
        for(std::size_t i=0;i<expected.size();++i) {
            const auto &want=expected[i];const auto &got=WorkOrderStateMachine::rules()[i];
            check(got.id==want.id&&got.from==want.from&&got.to==want.to&&got.action==want.action&&got.effect==want.effect);
            check(WorkOrderStateMachine::find(want.from,want.action)==&got);
        }
        for(auto state:statuses) {
            check(WorkOrderStateMachine::knownState(state));
            for(int value=0;value<=static_cast<int>(A::Close);++value) {
                const auto action=static_cast<A>(value);const WorkflowRule *want=nullptr;
                for(const auto &rule:expected) if(rule.from==state&&rule.action==action) want=&rule;
                const auto *got=WorkOrderStateMachine::find(state,action);
                check((want!=nullptr)==(got!=nullptr));
                if(state=="CLOSED"||state=="CANCELLED") check(got==nullptr);
            }
            check(WorkOrderStateMachine::processAllowed(state,ProcessEvent::Arrived)==(state=="IN_PROGRESS"));
            check(WorkOrderStateMachine::processAllowed(state,ProcessEvent::ProgressNote)==(state=="IN_PROGRESS"));
        }
        check(WorkOrderStateMachine::find("DRAFT",A::Accept)==nullptr);
        check(WorkOrderStateMachine::find("PENDING_REVIEW",A::Accept)==nullptr);
        check(WorkOrderStateMachine::find("PENDING_ACCEPT",A::VerifyPass)==nullptr);
        check(WorkOrderStateMachine::find("COMPLETED",A::Create)==nullptr);
        check(!WorkOrderStateMachine::knownState("ARRIVED")&&!WorkOrderStateMachine::knownState("PROGRESS_NOTE"));
        check(WorkOrderStateMachine::processRules()[0].id=="E-01"&&WorkOrderStateMachine::processRules()[1].id=="E-02");
        check(WorkOrderStateMachine::find("E-01",A::Complete)==nullptr);
        check(WorkOrderStateMachine::find("IN_PROGRESS",static_cast<A>(999))==nullptr);
        std::cout<<"PASS "<<checks<<" pure state machine checks; all T rules and separate E events; no business writes\n";return 0;
    }catch(const std::exception &e){std::cerr<<e.what()<<'\n';return 1;}
}
